fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 to n-1
    let mut divisor: i8 = 2;
    
    while divisor < n {
        // If n is divisible by divisor, it's not prime
        if n % divisor == 0 {
            return false;
        }
        divisor += 1;
    }
    
    // If no divisors found, n is prime
    true
}